using System;
using Vela.Context;
using Microsoft.Xrm.Sdk;

namespace Vela.Steps
{
    /// <summary>
    /// Typed-image terminals: variants of <c>Handle(...)</c> that pass the handler a generated projection of the
    /// step's captured pre/post image instead of the full early-bound entity. The projection exposes only the
    /// columns the step declared in <c>WithPreImage(...)</c> / <c>WithPostImage(...)</c>, so reading an uncaptured
    /// column is a compile error rather than a silent <c>null</c>. The projection type name is generated by the
    /// build-time source generator; the developer names it once in the handler's parameter.
    /// </summary>
    /// <remarks>
    /// These are extension methods (not part of the generated fluent surface) so the large generated builder is
    /// left untouched. The fluent config object is the underlying <see cref="StepBuilder{TEntity}"/>, so each
    /// terminal casts to it and retains a wrapper delegate that materializes the projection (via
    /// <see cref="ImageProjector"/>) then calls the user handler. Retained-delegate dispatch makes this work.
    /// </remarks>
    public static class TypedImageHandlers
    {
        // ---- Create PostOperation: post-image ------------------------------------------------------

        /// <summary>Binds a handler that receives a projection of the captured post-image.</summary>
        public static void Handle<TEntity, TPostImage>(
            this ICreatePostOperationConfig<TEntity> config,
            Action<ICreatePostContext<TEntity>, TPostImage?> handler)
            where TEntity : Entity
            where TPostImage : class, new()
        {
            RequireHandler(handler);
            Action<ICreatePostContext<TEntity>> wrapper = ctx => handler(ctx, ImageProjector.Project<TPostImage>(ctx.PostImage));
            Retain<TEntity>(config, wrapper, handler.Method.Name);
        }

        // ---- Update PreOperation: pre-image --------------------------------------------------------

        /// <summary>Binds a handler that receives a projection of the captured pre-image.</summary>
        public static void Handle<TEntity, TPreImage>(
            this IUpdatePreOperationConfig<TEntity> config,
            Action<IUpdatePreContext<TEntity>, TPreImage?> handler)
            where TEntity : Entity
            where TPreImage : class, new()
        {
            RequireHandler(handler);
            Action<IUpdatePreContext<TEntity>> wrapper = ctx => handler(ctx, ImageProjector.Project<TPreImage>(ctx.PreImage));
            Retain<TEntity>(config, wrapper, handler.Method.Name);
        }

        // ---- Update PostOperation: pre and/or post image -------------------------------------------

        /// <summary>Binds a handler that receives projections of both the captured pre- and post-image.</summary>
        public static void Handle<TEntity, TPreImage, TPostImage>(
            this IUpdatePostOperationConfig<TEntity> config,
            Action<IUpdatePostContext<TEntity>, TPreImage?, TPostImage?> handler)
            where TEntity : Entity
            where TPreImage : class, new()
            where TPostImage : class, new()
        {
            RequireHandler(handler);
            Action<IUpdatePostContext<TEntity>> wrapper = ctx =>
                handler(ctx, ImageProjector.Project<TPreImage>(ctx.PreImage), ImageProjector.Project<TPostImage>(ctx.PostImage));
            Retain<TEntity>(config, wrapper, handler.Method.Name);
        }

        /// <summary>Binds a handler that receives a projection of the captured pre-image only.</summary>
        public static void HandleWithPreImage<TEntity, TPreImage>(
            this IUpdatePostOperationConfig<TEntity> config,
            Action<IUpdatePostContext<TEntity>, TPreImage?> handler)
            where TEntity : Entity
            where TPreImage : class, new()
        {
            RequireHandler(handler);
            Action<IUpdatePostContext<TEntity>> wrapper = ctx => handler(ctx, ImageProjector.Project<TPreImage>(ctx.PreImage));
            Retain<TEntity>(config, wrapper, handler.Method.Name);
        }

        /// <summary>Binds a handler that receives a projection of the captured post-image only.</summary>
        public static void HandleWithPostImage<TEntity, TPostImage>(
            this IUpdatePostOperationConfig<TEntity> config,
            Action<IUpdatePostContext<TEntity>, TPostImage?> handler)
            where TEntity : Entity
            where TPostImage : class, new()
        {
            RequireHandler(handler);
            Action<IUpdatePostContext<TEntity>> wrapper = ctx => handler(ctx, ImageProjector.Project<TPostImage>(ctx.PostImage));
            Retain<TEntity>(config, wrapper, handler.Method.Name);
        }

        // ---- Delete Pre/PostOperation: pre-image ---------------------------------------------------

        /// <summary>Binds a handler that receives a projection of the captured pre-image.</summary>
        public static void Handle<TEntity, TPreImage>(
            this IDeletePreOperationConfig<TEntity> config,
            Action<IDeletePreContext<TEntity>, TPreImage?> handler)
            where TEntity : Entity
            where TPreImage : class, new()
        {
            RequireHandler(handler);
            Action<IDeletePreContext<TEntity>> wrapper = ctx => handler(ctx, ImageProjector.Project<TPreImage>(ctx.PreImage));
            Retain<TEntity>(config, wrapper, handler.Method.Name);
        }

        /// <summary>Binds a handler that receives a projection of the captured pre-image.</summary>
        public static void Handle<TEntity, TPreImage>(
            this IDeletePostOperationConfig<TEntity> config,
            Action<IDeletePostContext<TEntity>, TPreImage?> handler)
            where TEntity : Entity
            where TPreImage : class, new()
        {
            RequireHandler(handler);
            Action<IDeletePostContext<TEntity>> wrapper = ctx => handler(ctx, ImageProjector.Project<TPreImage>(ctx.PreImage));
            Retain<TEntity>(config, wrapper, handler.Method.Name);
        }

        // ---- Typed On<TRequest>() path -------------------------------------------------------------
        // The handler receives the generic message context IMessagePostContext<TRequest> (as today), and the
        // wrapper reads the image off its two-argument entity variant IMessagePostContext<TRequest, TEntity>,
        // which the unified dispatch builds from the wrapper's own parameter type.

        /// <summary>Typed path: handler receives a projection of the captured pre-image.</summary>
        public static void Handle<TEntity, TRequest, TPreImage>(
            this ITypedPreOperationConfig<TEntity, TRequest> config,
            Action<IMessagePreContext<TRequest>, TPreImage?> handler)
            where TEntity : Entity
            where TRequest : OrganizationRequest, new()
            where TPreImage : class, new()
        {
            RequireHandler(handler);
            Action<IMessagePreContext<TRequest, TEntity>> wrapper = ctx => handler(ctx, ImageProjector.Project<TPreImage>(ctx.PreImage));
            Retain<TEntity>(config, wrapper, handler.Method.Name);
        }

        /// <summary>Typed path: handler receives projections of both the captured pre- and post-image.</summary>
        public static void Handle<TEntity, TRequest, TPreImage, TPostImage>(
            this ITypedPostOperationConfig<TEntity, TRequest> config,
            Action<IMessagePostContext<TRequest>, TPreImage?, TPostImage?> handler)
            where TEntity : Entity
            where TRequest : OrganizationRequest, new()
            where TPreImage : class, new()
            where TPostImage : class, new()
        {
            RequireHandler(handler);
            Action<IMessagePostContext<TRequest, TEntity>> wrapper = ctx =>
                handler(ctx, ImageProjector.Project<TPreImage>(ctx.PreImage), ImageProjector.Project<TPostImage>(ctx.PostImage));
            Retain<TEntity>(config, wrapper, handler.Method.Name);
        }

        /// <summary>Typed path: handler receives a projection of the captured pre-image only.</summary>
        public static void HandleWithPreImage<TEntity, TRequest, TPreImage>(
            this ITypedPostOperationConfig<TEntity, TRequest> config,
            Action<IMessagePostContext<TRequest>, TPreImage?> handler)
            where TEntity : Entity
            where TRequest : OrganizationRequest, new()
            where TPreImage : class, new()
        {
            RequireHandler(handler);
            Action<IMessagePostContext<TRequest, TEntity>> wrapper = ctx => handler(ctx, ImageProjector.Project<TPreImage>(ctx.PreImage));
            Retain<TEntity>(config, wrapper, handler.Method.Name);
        }

        /// <summary>Typed path: handler receives a projection of the captured post-image only.</summary>
        public static void HandleWithPostImage<TEntity, TRequest, TPostImage>(
            this ITypedPostOperationConfig<TEntity, TRequest> config,
            Action<IMessagePostContext<TRequest>, TPostImage?> handler)
            where TEntity : Entity
            where TRequest : OrganizationRequest, new()
            where TPostImage : class, new()
        {
            RequireHandler(handler);
            Action<IMessagePostContext<TRequest, TEntity>> wrapper = ctx => handler(ctx, ImageProjector.Project<TPostImage>(ctx.PostImage));
            Retain<TEntity>(config, wrapper, handler.Method.Name);
        }

        private static void RequireHandler(Delegate handler)
        {
            if (handler == null)
            {
                throw new ArgumentNullException(nameof(handler));
            }
        }

        // Retains the wrapper delegate on the underlying builder (guided StepBuilder or typed adapter, both
        // IRuntimeHandlerHost) for direct dispatch, recording the user handler's method name for the manifest.
        private static void Retain<TEntity>(IFluentStep config, Delegate wrapper, string manifestMethodName)
            where TEntity : Entity
        {
            if (config == null)
            {
                throw new ArgumentNullException(nameof(config));
            }

            ((IRuntimeHandlerHost)config).SetRuntimeHandler(wrapper, manifestMethodName);
        }
    }
}
